      "content": "/**
 * Returns true if the provided value is a finite number.
 * @param {*} x - The value to check.
 * @returns {boolean} True if x is a finite number, otherwise false.
 */
export function isFiniteNumber(x) {
  return typeof x === 'number' && Number.isFinite(x);
}
",
      "reason": "Implement a function that checks for finite numbers, handling NaN and ±Infinity."
    },
    {
      "type": "create_file",
      "path": "src/util/isFiniteNumber.test.js",
      "content": "// Import the function under test and the node:test assertion library
import { strict as assert } from 'node:assert';
import { isFiniteNumber } from './isFiniteNumber.js';

// Create a test suite
describe('isFiniteNumber', () => {
  test('returns true for regular finite numbers', () => {
    assert.strictEqual(isFiniteNumber(0), true);
    assert.strictEqual(isFiniteNumber(42), true);
    assert.strictEqual(isFiniteNumber(-3.14), true);
    assert.strictEqual(isFiniteNumber(0.000001), true);
  });

  test('returns false for NaN', () => {
    assert.strictEqual(isFiniteNumber(NaN), false);
  });

  test('returns false for positive Infinity', () => {
    assert.strictEqual(isFiniteNumber(Infinity), false);
  });

  test('returns false for negative Infinity', () => {
    assert.strictEqual(isFiniteNumber(-Infinity), false);
  });

  test('returns false for non-number values', () => {
    assert.strictEqual(isFiniteNumber('123'), false);
    assert.strictEqual(isFiniteNumber(null), false);
    assert.strictEqual(isFiniteNumber(undefined), false);
    assert.strictEqual(isFiniteNumber(true), false);
    assert.strictEqual(isFiniteNumber({}), false);
  });
});
",
      "reason": "Unit tests using node:test and assert to verify the behavior of isFiniteNumber."
    }
  ]
}

